import unittest

from solution import parse_measurements


class ParseMeasurementsTests(unittest.TestCase):
    def test_standard_csv_trimming_and_order(self):
        text = ' name , value , unit\r\n"a,b",  12 , kg\r\nplain,, tail '
        self.assertEqual(parse_measurements(text), [
            ("name", "value", "unit"),
            ("a,b", "12", "kg"),
            ("plain", "", "tail"),
        ])

    def test_empty_input_and_blank_records_are_omitted(self):
        self.assertEqual(parse_measurements(""), [])
        text = '\n   \n  , \t,   \nvalue, ,\n\n'
        self.assertEqual(parse_measurements(text), [("value", "", "")])

    def test_record_with_one_non_whitespace_cell_is_retained(self):
        self.assertEqual(parse_measurements(' , x , \n'), [("", "x", "")])

    def test_quoted_newline_and_escaped_quote(self):
        text = '"line one\nline two","a""b"\n'
        self.assertEqual(parse_measurements(text), [
            ("line one\nline two", 'a"b')
        ])

    def test_each_result_is_new_independent_data(self):
        first = parse_measurements("a,b\n")
        second = parse_measurements("a,b\n")
        first.append(("changed",))
        self.assertEqual(second, [("a", "b")])

    def test_non_string_input_raises_type_error(self):
        for value in (None, b"a,b", 1, ["a,b"]):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    parse_measurements(value)

    def test_malformed_csv_raises_value_error(self):
        with self.assertRaises(ValueError):
            parse_measurements('"unterminated')


if __name__ == "__main__":
    unittest.main()

